      inputId = "date_filter",
      label = "Select Date Range:",
      min = tryCatch({
        if(exists("long_data") && nrow(long_data) &gt; 0) {
          min(long_data$sensor_date, na.rm = TRUE)
        } else {
          as.POSIXct("2023-10-14")
